using System.Collections.Immutable;
using System.Globalization;

namespace Delta.ECS.Generators;

/// <summary>Templates for generated Where delegates, views and interception shims.</summary>
internal static class GeneratedWhereTemplates
{
    private const string InterceptorHeader = """
        // <auto-generated />
        #nullable enable
        #pragma warning disable CS0436

        """;
    internal static string RenderInterceptor(WhereInterceptionSite site)
    {
        PredicateModel shape = site.Shape;
        TerminalModel terminal = site.Terminal;
        SignatureProjection terminalSlots = terminal.Api.Signature;
        string hash = GeneratorSupport.StableName(shape.Key);
        string terminalHash = GeneratorSupport.StableName(terminal.SignatureKey);
        string[] viewTypeArguments = shape.HasContext
            ? new[] { InterceptedPredicateContextType(site) }.Concat(site.PredicateComponents).ToArray()
            : site.PredicateComponents;
        string viewType = InNamespace(shape.Namespace, "GeneratedWhereQuery_" + hash);
        string usings = GeneratorTemplates.InterceptorUsings(site.Usings);
        string predicate = RenderInterceptedPredicate(site);
        string action = terminal.IsCallback && !terminal.IsFunctor ? RenderInterceptedAction(site) : string.Empty;
        string loop = terminal.HasValues
            ? RenderInterceptedStructuralLoop(site, values: true)
            : terminal.IsCallback ? RenderInterceptedWhereLoop(site) : RenderInterceptedStructuralLoop(site);
        string operationResult = terminal.IsCallback
            ? "global::Delta.ECS.EcsOperation"
            : "global::Delta.ECS.EcsResultOperation<int>";
        string resultGeneric = terminal.IsCallback && terminal.IsFunctor
            ? terminal.HasContext
                ? $"<{terminal.ContextType}, {terminal.FunctorType}>"
                : $"<{terminal.FunctorType}>"
            : string.Empty;
        string executeInvocation = terminal.HasValues
            ? $$"""Execute_{{site.Id}}(operationView.World, in query{{(terminalSlots.HasExplicitIds ? ", " + (terminalSlots.HasDynamicIds ? "operationComponentIds" : terminalSlots.ComponentIdListArgument()) : string.Empty)}}{{(terminal.Arity == 0 ? string.Empty : ", " + terminalSlots.ValueNames("operationValue"))}}{{(shape.HasContext ? ", ref operationView.PredicateContext" : string.Empty)}})"""
            : $$"""Execute_{{site.Id}}(operationView.World, in query{{(terminalSlots.HasExplicitIds ? ", " + (terminalSlots.HasDynamicIds ? "operationComponentIds" : terminalSlots.ComponentIdListArgument()) : string.Empty)}}{{(shape.HasContext ? ", ref operationView.PredicateContext" : string.Empty)}}{{(terminal.IsFunctor && terminal.HasContext ? ", ref operationContext" : string.Empty)}}{{(terminal.IsFunctor ? ", " + SignatureProjection.ContextArgument(terminal.FunctorPassMode, terminal.IsCallback ? "operationAction" : "action") : string.Empty)}})""";
        string interceptSignature = terminal.HasValues
            ? RenderInterceptedValueSignature(site)
            : terminal.IsCallback
            ? terminal.IsFunctor
                ? $$""", {{(terminal.HasContext ? "ref " + terminal.ContextType + " context, " : string.Empty)}}{{SignatureProjection.ContextParameter(terminal.FunctorPassMode, terminal.FunctorType!, "action")}})"""
                : $$""", {{InNamespace(shape.Namespace, "GeneratedWhereAction_" + hash + "_" + terminalHash)}}{{SignatureProjection.TypeArguments(site.ActionComponents)}} _)"""
            : terminalSlots.HasExplicitIds
                ? ", " + terminalSlots.ComponentIdParameters() + ")"
                : ")";
        string member = $$"""
            {{site.Attribute}}
            internal static {{operationResult}}{{resultGeneric}} Intercept_{{site.Id}}(this {{viewType}}{{SignatureProjection.TypeArguments(viewTypeArguments)}} view{{interceptSignature}}
            {
                global::Delta.ECS.Query query = view.Query;
                var operationView = view;
            {{(terminalSlots.HasDynamicIds ? "global::Delta.ECS.ComponentId[] operationComponentIds = componentIds.ToArray();" : string.Empty)}}
            {{(terminal.HasValues ? string.Join("\n", GeneratorTemplates.Indexed(terminal.Arity, index => $"{site.ActionComponents[index]} operationValue{index} = value{index};")) : string.Empty)}}
            {{(terminal.IsCallback && terminal.IsFunctor
                ? terminal.HasContext
                    ? $$"""return new global::Delta.ECS.EcsOperation<{{terminal.ContextType}}, {{terminal.FunctorType}}>(context, action, (ref {{terminal.ContextType}} operationContext, ref {{terminal.FunctorType}} operationAction) => {{executeInvocation}});"""
                    : $$"""return new global::Delta.ECS.EcsOperation<{{terminal.FunctorType}}>(action, (ref {{terminal.FunctorType}} operationAction) => {{executeInvocation}});"""
                : terminal.IsCallback
                    ? $$"""return new global::Delta.ECS.EcsOperation(() => {{executeInvocation}});"""
                    : $$"""return new global::Delta.ECS.EcsResultOperation<int>(() => {{executeInvocation}});""")}}
            }
            """;
        string members = GeneratorTemplates.JoinNonEmpty(new[] { predicate, action, loop, member });
        string source = $$"""
            {{InterceptorHeader}}{{(usings.Length == 0 ? string.Empty : usings + "\n")}}
            namespace Delta.ECS.Generated
            {

            file static class GeneratedWhereInterceptor_{{site.Id}}
            {
            {{GeneratorTemplates.Indent(members, "    ")}}
            }
            {{GeneratorTemplates.InterceptorSourceFooter}}
            """;
        return GeneratedSourceFormatter.Format(source);
    }

    private static string RenderInterceptedValueSignature(WhereInterceptionSite site)
        => ", " + RenderValueParameters(site.Terminal.Api.Signature, site.Terminal.Components) + ")";

    private static string RenderInterceptedPredicate(WhereInterceptionSite site)
        => RenderInterceptedCallback(site, predicate: true);

    private static string RenderInterceptedAction(WhereInterceptionSite site)
        => RenderInterceptedCallback(site, predicate: false);

    private static string RenderInterceptedCallback(WhereInterceptionSite site, bool predicate)
    {
        PredicateModel shape = site.Shape;
        TerminalModel terminal = site.Terminal;
        SignatureProjection slots = predicate ? shape.Api.Signature : terminal.Api.Signature;
        CallSiteBinding binding = predicate ? site.PredicateBinding : site.ActionBinding;
        string[] componentTypes = predicate ? site.PredicateComponents : site.ActionComponents;
        string[] parameters = binding.LambdaParameterNames;
        int parameterIndex = 0;
        bool hasEntity = predicate ? shape.HasEntity : terminal.HasEntity;
        string[] prefixes = predicate
            ? new[]
            {
                shape.HasContext ? $"ref {InterceptedPredicateContextType(site)} {parameters[parameterIndex++]}" : string.Empty,
                hasEntity ? $"Entity {parameters[parameterIndex++]}" : string.Empty
            }
            : new[] { hasEntity ? $"EntityRef {parameters[parameterIndex++]}" : string.Empty };
        string[] declarations = prefixes
            .Concat(Enumerable.Range(0, slots.Arity).Select(index =>
                slots.ComponentParameter(index, componentTypes[index], parameters[parameterIndex++])))
            .Where(static declaration => declaration.Length != 0)
            .ToArray();
        string body = binding.LambdaBodyIsBlock
            ? GeneratorTemplates.Indent(binding.LambdaBody!, "        ")
            : binding.LambdaBody is { } expression
                ? predicate ? $$"""        return {{expression}};""" : $$"""        {{expression}};"""
                : $$"""        {{(predicate ? "return " : string.Empty)}}{{MethodGroupInvocation(binding.MethodGroupTarget!, predicate ? shape.HasContext : terminal.HasContext, hasEntity, slots, parameters)}};""";
        string returnType = predicate ? "bool" : "void";
        string methodName = predicate ? "Predicate" : "Action";
        return $$"""
            [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
            private static {{returnType}} {{methodName}}_{{site.Id}}({{string.Join(", ", declarations)}})
            {
            {{body}}
            }

            """;
    }

    private static string MethodGroupInvocation(
        string target,
        bool hasContext,
        bool hasEntity,
        SignatureProjection slots,
        IReadOnlyList<string> parameters)
    {
        int parameterIndex = 0;
        string[] prefix =
        {
            hasContext ? "ref " + parameters[parameterIndex++] : string.Empty,
            hasEntity ? parameters[parameterIndex++] : string.Empty
        };
        string[] arguments = prefix
            .Concat(Enumerable.Range(0, slots.Arity)
                .Select(index => slots.ComponentArgument(index, parameters[parameterIndex++])))
            .Where(static argument => argument.Length != 0)
            .ToArray();
        return $"{target}({string.Join(", ", arguments)})";
    }

    private static string RenderInterceptedWhereLoop(WhereInterceptionSite site)
    {
        PredicateModel shape = site.Shape;
        TerminalModel terminal = site.Terminal;
        SignatureProjection predicateSlots = shape.Api.Signature;
        SignatureProjection terminalSlots = terminal.Api.Signature;
        string executeName = "Execute_" + site.Id;
        string[] signatureArguments = new[]
        {
            "global::Delta.ECS.World world",
            "in global::Delta.ECS.Query query",
            shape.HasContext ? "ref " + InterceptedPredicateContextType(site) + " predicateContext" : string.Empty,
            terminal.IsFunctor && terminal.HasContext ? "ref " + terminal.ContextType + " context" : string.Empty,
            terminal.IsFunctor
                ? SignatureProjection.ContextParameter(terminal.FunctorPassMode, terminal.FunctorType!, "action")
                : string.Empty
        }.Where(static argument => argument.Length != 0).ToArray();

        int accessCount = shape.Arity + terminal.Arity;
        string accesses = GeneratorTemplates.JoinIndexed(accessCount, index =>
        {
            string componentType = index < shape.Arity ? site.PredicateComponents[index] : site.ActionComponents[index - shape.Arity];
            ComponentModel component = index < shape.Arity
                ? shape.ComponentModels[index]
                : terminal.ComponentModels[index - shape.Arity];
            string accessKind = component.IsWrite ? "Write" : "Read";
            return $$"""var access{{index}} = global::Delta.ECS.GeneratedForEachRuntime.GetPrepared{{accessKind}}Access<{{componentType}}>(in query);""";
        }, "\n");
        string rowDeclarations = GeneratorTemplates.JoinIndexed(accessCount, index =>
        {
            string componentType = index < shape.Arity ? site.PredicateComponents[index] : site.ActionComponents[index - shape.Arity];
            return $$"""ref {{componentType}} row{{index}} = ref global::System.Runtime.CompilerServices.Unsafe.NullRef<{{componentType}}>();""";
        }, "\n");
        string rowBindings = GeneratorTemplates.JoinIndexed(accessCount, index =>
        {
            string componentType = index < shape.Arity ? site.PredicateComponents[index] : site.ActionComponents[index - shape.Arity];
            return $$"""row{{index}} = ref global::Delta.ECS.GeneratedForEachRuntime.GetGeneratedArrayReference(slots.GetGeneratedArray<{{componentType}}>(access{{index}}));""";
        }, "\n");
        string predicateArguments = string.Join(", ", new[]
        {
            shape.HasContext ? "ref predicateContext" : string.Empty,
            shape.HasEntity ? "__whereEntity_" + site.Id : string.Empty
        }.Concat(Enumerable.Range(0, shape.Arity)
            .Select(index => predicateSlots.ComponentArgument(index, $"row{index}")))
        .Where(static argument => argument.Length != 0));
        string taggedPredicateArguments = string.Join(", ", new[]
        {
            shape.HasContext ? "ref predicateContext" : string.Empty,
            shape.HasEntity ? "__whereEntity_" + site.Id : string.Empty
        }.Concat(Enumerable.Range(0, shape.Arity)
            .Select(index => predicateSlots.ComponentArgument(index, $"taggedRow{index}")))
        .Where(static argument => argument.Length != 0));
        bool needsEntity = shape.HasEntity || terminal.IsGeneratedEntityConsumer;
        string TerminalCall(IReadOnlyList<string> rowNames) => $$"""
            {{(terminal.IsFunctor ? "action.Invoke" : "Action_" + site.Id)}}({{string.Join(", ", new[]
                {
                    terminal.IsFunctor && terminal.HasContext ? "ref context" : string.Empty,
                    terminal.HasEntity ? "__whereEntityRef_" + site.Id : string.Empty
                }.Concat(Enumerable.Range(0, terminal.Arity)
                    .Select(index => terminalSlots.ComponentArgument(index, rowNames[shape.Arity + index])))
                .Where(static argument => argument.Length != 0))}});
            """;
        string terminalCall = TerminalCall(Enumerable.Range(0, accessCount).Select(static index => "row" + index).ToArray());
        string taggedTerminalCall = TerminalCall(Enumerable.Range(0, accessCount).Select(static index => "taggedRow" + index).ToArray());
        string entityBody = GeneratorTemplates.JoinNonEmpty(new[]
        {
            needsEntity
                ? $$"""Entity __whereEntity_{{site.Id}} = global::System.Runtime.CompilerServices.Unsafe.Add(ref firstEntity, index);"""
                : string.Empty,
            terminal.HasEntity
                ? $$"""EntityRef __whereEntityRef_{{site.Id}} = slots.GetEntityRef(index);"""
                : string.Empty,
            GeneratorTemplates.RenderBlock($"if (Predicate_{site.Id}({predicateArguments}))", terminalCall)
        });
        string denseIteration = GeneratorTemplates.JoinNonEmpty(new[]
        {
            "int count = slots.Count;",
            GeneratorTemplates.RenderBlock(
                "for (int index = 0; index < count; index++)",
                GeneratorTemplates.JoinNonEmpty(new[]
                {
                    entityBody,
                    GeneratorTemplates.JoinIndexed(accessCount, index =>
                        $$"""row{{index}} = ref global::System.Runtime.CompilerServices.Unsafe.Add(ref row{{index}}, 1);""", "\n")
                    }))
        });
        string taggedIteration = GeneratorTemplates.JoinNonEmpty(new[]
        {
            "if (slots.TryGetTagSlots(out var tagSlots))",
            "{",
            "    for (int tagIndex = 0; tagIndex < tagSlots.Length; tagIndex++)",
            "    {",
            "        int slotIndex = tagSlots[tagIndex];",
            needsEntity
                ? $$"""        Entity __whereEntity_{{site.Id}} = global::System.Runtime.CompilerServices.Unsafe.Add(ref firstEntity, slotIndex);"""
                : string.Empty,
            terminal.HasEntity
                ? $$"""        EntityRef __whereEntityRef_{{site.Id}} = slots.GetEntityRefAtSlot(slotIndex);"""
                : string.Empty,
            GeneratorTemplates.JoinIndexed(accessCount, index =>
                $$"""        ref {{(index < shape.Arity ? site.PredicateComponents[index] : site.ActionComponents[index - shape.Arity])}} taggedRow{{index}} = ref global::System.Runtime.CompilerServices.Unsafe.Add(ref row{{index}}, slotIndex);""", "\n"),
            GeneratorTemplates.RenderBlock($"if (Predicate_{site.Id}({taggedPredicateArguments}))", taggedTerminalCall)
        }.Where(static line => line.Length != 0).Select(static line => line + "\n").Append("    }\n}"));
        string iteration = GeneratorTemplates.JoinNonEmpty(new[]
        {
            needsEntity
                ? "ref global::Delta.ECS.Entity firstEntity = ref slots.GetGeneratedEntityReference();"
                : string.Empty,
            taggedIteration,
            GeneratorTemplates.RenderBlock("else", denseIteration)
        });
        string executionBody = GeneratorTemplates.JoinNonEmpty(new[]
        {
            "using var execution = global::Delta.ECS.GeneratedForEachRuntime.OpenDense(world, in query);",
            accesses,
            rowDeclarations,
            $$"""execution.MarkArchetypeWrites({{GeneratorTemplates.WriteSpan(shape.ComponentModels.Concat(terminal.ComponentModels))}});""",
            GeneratorTemplates.RenderBlock(
                "while (execution.MoveNextTrusted(out var slots))",
                GeneratorTemplates.JoinNonEmpty(new[] { rowBindings, iteration }))
        });
        string executeDeclaration = $$"""
            [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
            private static void {{executeName}}({{string.Join(", ", signatureArguments)}})
            """.Trim();
        return GeneratorTemplates.RenderBlock(
            executeDeclaration,
            executionBody);
    }

    private static string RenderInterceptedStructuralLoop(WhereInterceptionSite site, bool values = false)
    {
        PredicateModel shape = site.Shape;
        TerminalModel terminal = site.Terminal;
        SignatureProjection terminalSlots = terminal.Api.Signature;
        string invokerName = (values ? "Value" : string.Empty) + "StructuralInvoker_" + site.Id;
        string executeName = "Execute_" + site.Id;
        string initializerType = values
            ? WhereValueInitializerName(terminal.Arity) + SignatureProjection.TypeArguments(site.ActionComponents)
            : string.Empty;
        string fields = GeneratorTemplates.JoinNonEmpty(new[]
        {
            shape.HasContext ? $"private {InterceptedPredicateContextType(site)} _predicateContext;" : string.Empty,
            values ? $"private {initializerType} _initializer;" : string.Empty,
            GeneratorTemplates.JoinNonEmpty(GeneratorTemplates.Indexed(shape.Arity,
                index => $$"""private readonly int _access{{index}};"""))
        });
        string constructorParameters = string.Join(", ", new[]
        {
            shape.HasContext ? $"{InterceptedPredicateContextType(site)} predicateContext" : string.Empty,
            values ? terminalSlots.ComponentIdParameters() : string.Empty,
            values ? terminalSlots.ValueParameters(types: site.ActionComponents) : string.Empty,
            GeneratorTemplates.JoinIndexed(shape.Arity, index => $$"""int access{{index}}""")
        }.Where(static value => value.Length != 0));
        string assignments = GeneratorTemplates.JoinNonEmpty(new[]
        {
            shape.HasContext ? "_predicateContext = predicateContext;" : string.Empty,
            values ? $"_initializer = new {initializerType}({GeneratorTemplates.JoinIndexed(terminal.Arity, index => terminalSlots.ComponentIdArgument(index) + ", in value" + index, ", ")});" : string.Empty,
            GeneratorTemplates.JoinNonEmpty(GeneratorTemplates.Indexed(shape.Arity,
                index => $$"""_access{{index}} = access{{index}};"""))
        });
        string processRunInitializer = values ? ", ref _initializer" : string.Empty;
        string operationBody = GeneratorTemplates.JoinNonEmpty(new[]
        {
            """
                int count = slots.PhysicalCount;
                if (count == 0)
                {
                    return;
                }
                bool hasSparseTagSlots = slots.TryGetTagSlots(out var tagSlots);
                int tagCursor = 0;
                """,
            RenderSlotLocals(shape.ComponentModels, site.PredicateComponents, "", elements: false),
            "int runStart = 0;",
            "bool runSelected = false;",
            shape.HasEntity
                ? "ref global::Delta.ECS.Entity firstEntity = ref slots.GetGeneratedEntityReference();"
                : string.Empty,
            GeneratorTemplates.RenderBlock(
                "for (int index = 0; index < count; index++)",
                string.Join("\n", new[]
                {
                    RenderSlotLocals(shape.ComponentModels, site.PredicateComponents, "", elements: true),
                    shape.HasEntity
                        ? "Entity entity = global::System.Runtime.CompilerServices.Unsafe.Add(ref firstEntity, index);"
                        : string.Empty,
                    "bool matchesQuery = !hasSparseTagSlots;",
                    "if (hasSparseTagSlots && tagCursor < tagSlots.Length && tagSlots[tagCursor] == index)",
                    "{",
                    "    tagCursor++;",
                    "    matchesQuery = true;",
                    "}",
                    $$"""bool selected = matchesQuery && Predicate_{{site.Id}}({{InterceptedPredicateArguments(shape, "_predicateContext")}});""",
                    $$"""
                        if (index != 0 && selected != runSelected)
                        {
                            context.ProcessRun(runStart, index - runStart, runSelected{{processRunInitializer}});
                            runStart = index;
                        }
                        """,
                    "runSelected = selected;"
                })),
            $$"""context.ProcessRun(runStart, count - runStart, runSelected{{processRunInitializer}});"""
        });
        string invokerExecute = GeneratorTemplates.RenderBlock(
            "public void Execute(ref GeneratedQuerySlots slots, ref GeneratedWhereStructuralContext context)",
            operationBody);
        if (shape.HasContext)
        {
            invokerExecute = GeneratorTemplates.JoinNonEmpty(new[]
            {
                invokerExecute,
                $$"""internal {{InterceptedPredicateContextType(site)}} PredicateContext => _predicateContext;"""
            }, "\n\n");
        }

        string invoker = GeneratorTemplates.RenderBlock(
            $$"""private struct {{invokerName}} : global::Delta.ECS.IGeneratedWhereStructuralInvoker""",
            GeneratorTemplates.JoinNonEmpty(new[] { fields }.Concat(new[]
            {
                GeneratorTemplates.RenderBlock($"internal {invokerName}({constructorParameters})", assignments),
                invokerExecute
            }), "\n\n"));
        string accessLines = GeneratorTemplates.JoinIndexed(shape.Arity, index =>
        {
            string accessKind = shape.ComponentModels[index].IsWrite ? "Write" : "Read";
            return $$"""var access{{index}} = global::Delta.ECS.GeneratedForEachRuntime.GetPrepared{{accessKind}}Access<{{site.PredicateComponents[index]}}>(in query);""";
        }, "\n");
        string invokerArguments = string.Join(", ", new[] { shape.HasContext ? "predicateContext" : string.Empty }
            .Concat(values ? new[]
            {
                terminalSlots.HasDynamicIds
                    ? "components"
                    : GeneratorTemplates.JoinIndexed(terminal.Arity, static index => "components[" + index + "]"),
                terminalSlots.ValueNames()
            } : Array.Empty<string>())
            .Concat(GeneratorTemplates.Indexed(shape.Arity, index =>
                $"global::Delta.ECS.GeneratedForEachRuntime.Get{(shape.ComponentModels[index].IsWrite ? "Write" : "Read")}QueryComponentIndex(access{index})"))
            .Where(static argument => argument.Length != 0));
        string componentSetup = terminal.Kind is not (TerminalKind.Add or TerminalKind.Remove)
            ? string.Empty
            : terminalSlots.HasDynamicIds
                ? GeneratorTemplates.JoinNonEmpty(new[]
                {
                    $"global::Delta.ECS.GeneratedForEachRuntime.ValidateComponentIdCount(componentIds, {terminal.Arity});",
                    terminalSlots.HasGenericSelectors
                        ? GeneratorTemplates.JoinIndexed(terminal.Arity, index =>
                            $"global::Delta.ECS.GeneratedForEachRuntime.ValidateComponentType<{site.ActionComponents[index]}>(world, componentIds[{index}]);", "\n")
                        : string.Empty,
                    "global::System.ReadOnlySpan<global::Delta.ECS.ComponentId> components = componentIds;"
                })
                : terminalSlots.HasExplicitIds
                    ? GeneratorTemplates.JoinNonEmpty(new[]
                    {
                        $"global::System.Span<global::Delta.ECS.ComponentId> components = stackalloc global::Delta.ECS.ComponentId[{terminal.Arity}];",
                        GeneratorTemplates.JoinIndexed(
                            terminal.Arity,
                            index => $$"""components[{{index}}] = {{terminalSlots.ComponentIdArgument(index)}};""",
                            "\n")
                    })
                    : $$"""global::System.ReadOnlySpan<global::Delta.ECS.ComponentId> components = {{GeneratorTemplates.PrimaryComponentIds("world", site.ActionComponents, namespaceName: shape.Namespace)}};""";

        string operationName = terminal.Kind switch
        {
            TerminalKind.Destroy => "Destroy",
            TerminalKind.Add => "Add",
            TerminalKind.Remove => "Remove",
            _ => string.Empty
        };
        string operation = $$"""
            int result = global::Delta.ECS.GeneratedForEachRuntime.ExecuteGeneratedWhere{{operationName}}(
                world,
                in query,
                ref invoker,
                {{GeneratorTemplates.WriteSpan(shape.ComponentModels.Concat(ImmutableArray<ComponentModel>.Empty))}}{{(terminal.Kind is TerminalKind.Add or TerminalKind.Remove ? ", components" : string.Empty)}});
            """;
        string executeBody = GeneratorTemplates.JoinNonEmpty(new[]
        {
            accessLines,
            componentSetup,
            $"var invoker = new {invokerName}({invokerArguments});",
            operation,
            shape.HasContext ? "predicateContext = invoker.PredicateContext;" : string.Empty,
            "return result;"
        });
        string valueParameters = values
            ? terminalSlots.ValueParameters(types: site.ActionComponents)
            : string.Empty;
        string execute = GeneratorTemplates.RenderBlock(
            $$"""private static int {{executeName}}(global::Delta.ECS.World world, in global::Delta.ECS.Query query{{(terminalSlots.HasExplicitIds ? ", " + terminalSlots.ComponentIdParameters() : string.Empty)}}{{(valueParameters.Length == 0 ? string.Empty : ", " + valueParameters)}}{{(shape.HasContext ? ", ref " + InterceptedPredicateContextType(site) + " predicateContext" : string.Empty)}})""",
            executeBody);
        return $$"""
            {{invoker}}

            {{execute}}
            """;
    }

    private static string InterceptedPredicateArguments(
        PredicateModel shape,
        string contextName = "predicateContext")
    {
        var arguments = new List<string>();
        if (shape.HasContext)
        {
            arguments.Add("ref " + contextName);
        }

        if (shape.HasEntity)
        {
            arguments.Add("entity");
        }

        arguments.Add(shape.Api.Signature.ComponentArguments());
        return string.Join(", ", arguments);
    }

    internal static string Render(PredicateModel shape)
    {
        string hash = GeneratorSupport.StableName(shape.Key);
        string predicate = RenderPredicateDelegate(shape, hash);
        string[] terminalMembers = shape.Terminals.Ordered()
            .SelectMany(terminal => new[]
            {
                RenderActionDelegate(terminal, hash) is { Length: > 0 } action
                    ? action
                    : null,
                RenderInvoker(shape, terminal, hash)
            })
            .OfType<string>()
            .ToArray();
        IEnumerable<string> componentSetKeys = shape.Terminals.Ordered()
            .Where(static terminal => terminal.Kind is TerminalKind.Add or TerminalKind.Remove
                && !terminal.Api.Signature.HasExplicitIds)
            .Select(static terminal => terminal.Arity)
            .Distinct()
            .OrderBy(static arity => arity)
            .Select(GeneratorTemplates.PrimaryComponentSetKeyDeclaration);
        string[] members = componentSetKeys
            .Concat(new[] { predicate.Length == 0 ? null : predicate })
            .Concat(terminalMembers)
            .Append(GeneratorTemplates.RenderBlock(ViewDeclaration(shape, hash), RenderViewBody(shape, hash)))
            .Append(shape.HasOrderedQuerySource ? RenderOrderedView(shape, hash) : null)
            .Append(GeneratorTemplates.ExtensionTemplate(
                "GeneratedWhereExtensions_" + hash,
                shape.IsFunctor,
                RenderExtensionBody(shape, hash)))
            .OfType<string>()
            .ToArray();
        return GeneratorTemplates.FileTemplate(new GeneratedFileModel(
            shape.Namespace,
            ImmutableArray.Create("using global::System;")
                .AddRange(GeneratorSupport.EcsNamespaceUsings(shape.Namespace)),
            members.ToImmutableArray()));
    }

    internal static string RenderValueInitializer(TerminalModel terminal)
        => GeneratorTemplates.FileTemplate(new GeneratedFileModel(
            "Delta.ECS",
            ImmutableArray<string>.Empty,
            ImmutableArray.Create(GeneratorTemplates.ValueInitializer(
                WhereValueInitializerName(terminal.Arity), terminal.Api.Signature, "T", "InitializeAdded", "internal"))));

    private static string RenderPredicateDelegate(PredicateModel shape, string hash)
    {
        if (shape.IsFunctor)
        {
            return string.Empty;
        }

        SignatureProjection slots = shape.Api.Signature;
        string[] parameters = new[]
            {
                shape.HasContext ? $"ref {PredicateContextType(shape)} context" : string.Empty,
                shape.HasEntity ? "Entity entity" : string.Empty
            }
            .Append(slots.ComponentParameters())
            .Where(static parameter => parameter.Length != 0)
            .ToArray();
        string declaration = $$"""
            public delegate bool GeneratedWherePredicate_{{hash}}{{PredicateGenericTypes(shape)}}({{string.Join(", ", parameters)}});
            """.Trim();
        return GeneratorTemplates.Declaration(shape.Api, declaration);
    }

    private static string RenderActionDelegate(TerminalModel terminal, string predicateHash)
    {
        if (!terminal.IsCallback || terminal.IsFunctor)
        {
            return string.Empty;
        }

        SignatureProjection slots = terminal.Api.Signature;
        string hash = GeneratorSupport.StableName(terminal.SignatureKey);
        string[] parameters = new[]
            {
                terminal.HasEntity ? "EntityRef entity" : string.Empty
            }
            .Append(slots.ComponentParameters(genericPrefix: "U"))
